package selfupdate

import (
	"archive/zip"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path"
	"runtime"
	"strings"
	"time"
)

// sumsAsset is the checksum list generated by release.yml, covering every zip in the
// Release.
const sumsAsset = "SHA256SUMS"

// maxBinarySize caps the size of the extracted binary so a malformed zip cannot fill
// the disk.
const maxBinarySize = 512 << 20 // 512 MiB

// Phase is a stage of the upgrade, used directly as the phase field in SSE events.
type Phase string

const (
	PhaseIdle     Phase = "idle"
	PhaseDownload Phase = "downloading"
	PhaseVerify   Phase = "verifying"
	PhaseExtract  Phase = "extracting"
	PhaseStaged   Phase = "staged"
	PhaseFailed   Phase = "failed"
)

// Progress is supplied by the caller to push progress to the frontend. pct is only
// meaningful during the download stage (0-100); other stages pass -1.
type Progress func(ph Phase, pct int, msg string)

// Stage downloads the current platform bundle for the given Release, verifies it and
// stages the new binary as pojun.new.
//
// It uses the full zip rather than a bare binary for two reasons: the existing
// releases' SHA256SUMS only covers zips, so using the zip needs no CI change and also
// works with historical releases already published; and the zip also carries skills/,
// leaving room for syncing builtin skills later. The only cost is downloading those few
// hundred KB of skills.
//
// Returning means staging is complete; the caller then shuts down gracefully and exits
// with ExitRestart.
func Stage(ctx context.Context, c *http.Client, rel *Release, currentVersion string, prog Progress) error {
	if prog == nil {
		prog = func(Phase, int, string) {}
	}
	p, err := ResolvePaths()
	if err != nil {
		return err
	}
	if err := checkWritable(p.Dir); err != nil {
		return err
	}

	binPath := p.New + ".part"
	defer func() { _ = os.Remove(binPath) }()

	// Download and verification use the shared implementation (bundle.go): the companion
	// binary pojun-hostd's self-replacement uses the same logic, so neither side grows its
	// own copy and eventually skips a check.
	// Temp files land in the program directory so the final rename is an atomic
	// same-filesystem operation.
	zipPath, err := FetchVerifiedZip(ctx, c, rel, p.Dir, prog)
	if err != nil {
		return err
	}
	defer func() { _ = os.Remove(zipPath) }()

	prog(PhaseExtract, -1, "Extracting and smoke testing…")
	if err := extractBinary(zipPath, binPath); err != nil {
		return err
	}
	if err := smokeTest(binPath); err != nil {
		return fmt.Errorf("the new version cannot run on this system: %w", err)
	}

	// Keep a separate sha256 of the staged file: the next startup verifies it once more
	// before swapping, so the file cannot be modified or corrupted between staging and the
	// restart.
	binSum, err := fileSHA256(binPath)
	if err != nil {
		return fmt.Errorf("compute checksum of the new binary: %w", err)
	}
	if err := os.WriteFile(p.Sum, []byte(binSum), 0o644); err != nil {
		return fmt.Errorf("write checksum: %w", err)
	}
	if err := os.Rename(binPath, p.New); err != nil {
		_ = os.Remove(p.Sum)
		return fmt.Errorf("stage new version: %w", err)
	}

	if err := writeMarker(p.Marker, marker{
		From:     currentVersion,
		To:       strings.TrimPrefix(rel.TagName, "v"),
		StagedAt: time.Now().Unix(),
	}); err != nil {
		// The marker only affects automatic rollback; the staged file itself is in place, so
		// the upgrade is not aborted over this.
		prog(PhaseStaged, -1, "Warning: writing the upgrade marker failed, this upgrade has no automatic rollback protection")
	}

	prog(PhaseStaged, 100, "The new version is ready, restarting…")
	return nil
}

// fetchSums downloads and parses SHA256SUMS, returning file name → hex digest.
func fetchSums(ctx context.Context, c *http.Client, rel *Release) (map[string]string, error) {
	asset, ok := rel.FindAsset(sumsAsset)
	if !ok {
		return nil, fmt.Errorf("this release has no %s, so integrity cannot be verified; refusing to upgrade", sumsAsset)
	}
	body, err := get(ctx, c, asset.URL)
	if err != nil {
		return nil, fmt.Errorf("download %s: %w", sumsAsset, err)
	}
	defer body.Close()

	raw, err := io.ReadAll(io.LimitReader(body, 1<<20))
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", sumsAsset, err)
	}
	out := parseSums(string(raw))
	if len(out) == 0 {
		return nil, fmt.Errorf("%s is empty or its format is unrecognized", sumsAsset)
	}
	return out, nil
}

// parseSums parses a sha256sum-style list, returning file name → hex digest.
//
// The first field must be 64 hex characters to be accepted. Checking only "exactly two
// fields" is not enough — any prose line with two words would be taken as a valid entry,
// stuffing garbage into the digest table while the real asset may then match a wrong
// digest.
func parseSums(raw string) map[string]string {
	out := map[string]string{}
	for line := range strings.Lines(raw) {
		// Format is "<sha256>  <filename>" (sha256sum uses two spaces; shasum's binary
		// mode prefixes the file name with *).
		fields := strings.Fields(strings.TrimSpace(line))
		if len(fields) != 2 || !isHexSHA256(fields[0]) {
			continue
		}
		name := strings.TrimPrefix(fields[1], "*")
		if name == "" {
			continue
		}
		out[name] = strings.ToLower(fields[0])
	}
	return out
}

func isHexSHA256(s string) bool {
	if len(s) != 64 {
		return false
	}
	for _, c := range s {
		switch {
		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
		default:
			return false
		}
	}
	return true
}

// download writes the asset to dst, computing SHA256 and reporting progress against
// Content-Length.
func download(ctx context.Context, c *http.Client, a Asset, dst string, prog Progress) (string, error) {
	body, err := get(ctx, c, a.URL)
	if err != nil {
		return "", fmt.Errorf("download %s: %w", a.Name, err)
	}
	defer body.Close()

	f, err := os.Create(dst)
	if err != nil {
		return "", fmt.Errorf("create temp file: %w", err)
	}
	defer f.Close()

	h := sha256.New()
	pw := &progressWriter{total: a.Size, prog: prog, name: a.Name, last: time.Now()}
	if _, err := io.Copy(io.MultiWriter(f, h, pw), body); err != nil {
		return "", fmt.Errorf("download interrupted: %w", err)
	}
	if err := f.Sync(); err != nil {
		return "", fmt.Errorf("failed to flush to disk: %w", err)
	}
	if a.Size > 0 && pw.written != a.Size {
		return "", fmt.Errorf("incomplete download: expected %d bytes, got %d bytes", a.Size, pw.written)
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// get issues a GET constrained by the whitelist and returns the response body.
func get(ctx context.Context, c *http.Client, rawURL string) (io.ReadCloser, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
	if err != nil {
		return nil, err
	}
	if err := checkURL(req.URL); err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", "pojun-selfupdate")
	resp, err := c.Do(req)
	if err != nil {
		return nil, err
	}
	if resp.StatusCode != http.StatusOK {
		resp.Body.Close()
		return nil, fmt.Errorf("HTTP %d", resp.StatusCode)
	}
	return resp.Body, nil
}

// extractBinary extracts the pojun executable from the release bundle.
//
// The structure inside the bundle is pojun-<version>-<os>-<arch>/pojun, but matching is
// by **base name** rather than building the full path: the version appears once in the
// bundle name, one wrong character fails the whole upgrade, and looking it up by base
// name is more resilient.
func extractBinary(zipPath, dst string) error {
	want := "pojun"
	if runtime.GOOS == "windows" {
		want = "pojun.exe"
	}
	zr, err := zip.OpenReader(zipPath)
	if err != nil {
		return fmt.Errorf("open release bundle: %w", err)
	}
	defer zr.Close()

	for _, entry := range zr.File {
		if entry.FileInfo().IsDir() || !strings.EqualFold(path.Base(entry.Name), want) {
			continue
		}
		rc, err := entry.Open()
		if err != nil {
			return fmt.Errorf("read %s: %w", entry.Name, err)
		}
		defer rc.Close()

		f, err := os.OpenFile(dst, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o755)
		if err != nil {
			return fmt.Errorf("write new binary: %w", err)
		}
		defer f.Close()

		n, err := io.Copy(f, io.LimitReader(rc, maxBinarySize+1))
		if err != nil {
			return fmt.Errorf("extract %s: %w", entry.Name, err)
		}
		if n > maxBinarySize {
			return fmt.Errorf("the executable inside the bundle exceeds %s; refusing to extract", humanSize(maxBinarySize))
		}
		if n == 0 {
			return fmt.Errorf("%s inside the bundle is an empty file", want)
		}
		return f.Sync()
	}
	return fmt.Errorf("%s was not found in the release bundle", want)
}

// checkWritable confirms up front that the directory is writable. Without it, running as
// non-root or having the binary in a system directory only fails at the swap moment,
// after tens of MB have been downloaded.
func checkWritable(dir string) error {
	probe, err := os.CreateTemp(dir, ".pojun-update-probe-*")
	if err != nil {
		return fmt.Errorf("program directory %s is not writable, cannot self-update (check permissions or upgrade manually): %w", dir, err)
	}
	name := probe.Name()
	_ = probe.Close()
	_ = os.Remove(name)
	return nil
}

// progressWriter counts written bytes and rate-limits reporting so not every 32KiB chunk
// pushes an SSE event.
type progressWriter struct {
	total   int64
	written int64
	name    string
	prog    Progress
	last    time.Time
}

func (w *progressWriter) Write(b []byte) (int, error) {
	w.written += int64(len(b))
	if time.Since(w.last) < 300*time.Millisecond {
		return len(b), nil
	}
	w.last = time.Now()
	pct := -1
	if w.total > 0 {
		pct = int(w.written * 100 / w.total)
	}
	w.prog(PhaseDownload, pct, fmt.Sprintf("Downloading %s / %s", humanSize(w.written), humanSize(w.total)))
	return len(b), nil
}

func humanSize(n int64) string {
	const unit = 1024
	if n < unit {
		return fmt.Sprintf("%d B", n)
	}
	div, exp := int64(unit), 0
	for v := n / unit; v >= unit; v /= unit {
		div *= unit
		exp++
	}
	return fmt.Sprintf("%.1f %cB", float64(n)/float64(div), "KMGT"[exp])
}

func short(sum string) string {
	if len(sum) > 12 {
		return sum[:12] + "…"
	}
	return sum
}
